with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'التطبيقات الميدانية والمختبرات العملية للأرصاد','مختبرات قياس عناصر الطقس وتحليل الرصد العلوي والخرائط الفضائية والرادارية ومشاريع التحقق والتنبؤ والإنذار.',43,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'التجارب والأجهزة والقياسات الميدانية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تحليل الحالات والمشاريع التطبيقية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit) as (values ('field-pressure-measurement-lab','مختبر قياس الضغط الجوي ومقارنة الأجهزة','التجربة العملية للبارومتر وتصحيح الضغط.','{"blocks":[{"type":"text","text":"يقدم هذا الدرس العملي مختبر قياس الضغط الجوي ومقارنة الأجهزة بوصفه نشاطاً تطبيقياً يربط المفاهيم النظرية ببيانات أو أجهزة أرصادية."},{"type":"text","text":"الهدف التطبيقي: التجربة العملية للبارومتر وتصحيح الضغط. ضمن إجراءات موثقة وقابلة للتكرار."},{"type":"text","text":"قبل البدء، تحدد الأدوات ومصادر البيانات والوحدات والفترة والموقع ومتطلبات السلامة المهنية."},{"type":"text","text":"تسجل حالة الجهاز أو مجموعة البيانات وإصدارها ومصدرها ووقت القياس أو الاستخراج."},{"type":"text","text":"تنفذ خطوات القياس أو التحليل بالتسلسل مع تسجيل الإعدادات والظروف المحيطة."},{"type":"text","text":"تجرى فحوص الجودة والاتساق وتوثق القراءات غير الصالحة أو القيود التي تؤثر في النتيجة."},{"type":"text","text":"تحلل النتائج باستخدام الجداول والرسوم والخرائط المناسبة مع توضيح الوحدات."},{"type":"text","text":"تقارن النتائج بمرجع مستقل أو قياس آخر لتقدير الفروق والتحقق من صلاحية الإجراء."},{"type":"text","text":"تكتب مناقشة علمية تفسر مصادر الخطأ وعدم اليقين وحدود التعميم."},{"type":"text","text":"يحفظ الناتج مع البيانات الخام وخطوات المعالجة والملفات الوصفية لسهولة إعادة التجربة."},{"type":"text","text":"مخرج النشاط: تقرير عملي يتضمن الهدف والمنهج والبيانات والنتائج والمناقشة والاستنتاجات."},{"type":"callout","text":"الخلاصة: المهارة العملية تكتمل عندما تكون القياسات موثقة والنتائج قابلة للتحقق وإعادة الإنتاج."}]}',4960,75,'["تنفيذ النشاط العملي وفق خطوات موثقة","فحص جودة القياسات والبيانات","إعداد تقرير وتحليل قابل لإعادة الإنتاج"]','التجارب والأجهزة والقياسات الميدانية'),
('field-temperature-sensor-lab','مختبر قياس الحرارة ومعايرة الحساسات','مقارنة الحساسات والاستجابة والتهوية.','{"blocks":[{"type":"text","text":"يقدم هذا الدرس العملي مختبر قياس الحرارة ومعايرة الحساسات بوصفه نشاطاً تطبيقياً يربط المفاهيم النظرية ببيانات أو أجهزة أرصادية."},{"type":"text","text":"الهدف التطبيقي: مقارنة الحساسات والاستجابة والتهوية. ضمن إجراءات موثقة وقابلة للتكرار."},{"type":"text","text":"قبل البدء، تحدد الأدوات ومصادر البيانات والوحدات والفترة والموقع ومتطلبات السلامة المهنية."},{"type":"text","text":"تسجل حالة الجهاز أو مجموعة البيانات وإصدارها ومصدرها ووقت القياس أو الاستخراج."},{"type":"text","text":"تنفذ خطوات القياس أو التحليل بالتسلسل مع تسجيل الإعدادات والظروف المحيطة."},{"type":"text","text":"تجرى فحوص الجودة والاتساق وتوثق القراءات غير الصالحة أو القيود التي تؤثر في النتيجة."},{"type":"text","text":"تحلل النتائج باستخدام الجداول والرسوم والخرائط المناسبة مع توضيح الوحدات."},{"type":"text","text":"تقارن النتائج بمرجع مستقل أو قياس آخر لتقدير الفروق والتحقق من صلاحية الإجراء."},{"type":"text","text":"تكتب مناقشة علمية تفسر مصادر الخطأ وعدم اليقين وحدود التعميم."},{"type":"text","text":"يحفظ الناتج مع البيانات الخام وخطوات المعالجة والملفات الوصفية لسهولة إعادة التجربة."},{"type":"text","text":"مخرج النشاط: تقرير عملي يتضمن الهدف والمنهج والبيانات والنتائج والمناقشة والاستنتاجات."},{"type":"callout","text":"الخلاصة: المهارة العملية تكتمل عندما تكون القياسات موثقة والنتائج قابلة للتحقق وإعادة الإنتاج."}]}',4970,75,'["تنفيذ النشاط العملي وفق خطوات موثقة","فحص جودة القياسات والبيانات","إعداد تقرير وتحليل قابل لإعادة الإنتاج"]','التجارب والأجهزة والقياسات الميدانية'),
