('field-national-service-capstone','مشروع تخرج متكامل لخدمة أرصاد وطنية','دمج الرصد والتحليل والتنبؤ والإنذار والتقييم.','{"blocks":[{"type":"text","text":"يقدم هذا الدرس العملي مشروع تخرج متكامل لخدمة أرصاد وطنية بوصفه نشاطاً تطبيقياً يربط المفاهيم النظرية ببيانات أو أجهزة أرصادية."},{"type":"text","text":"الهدف التطبيقي: دمج الرصد والتحليل والتنبؤ والإنذار والتقييم. ضمن إجراءات موثقة وقابلة للتكرار."},{"type":"text","text":"قبل البدء، تحدد الأدوات ومصادر البيانات والوحدات والفترة والموقع ومتطلبات السلامة المهنية."},{"type":"text","text":"تسجل حالة الجهاز أو مجموعة البيانات وإصدارها ومصدرها ووقت القياس أو الاستخراج."},{"type":"text","text":"تنفذ خطوات القياس أو التحليل بالتسلسل مع تسجيل الإعدادات والظروف المحيطة."},{"type":"text","text":"تجرى فحوص الجودة والاتساق وتوثق القراءات غير الصالحة أو القيود التي تؤثر في النتيجة."},{"type":"text","text":"تحلل النتائج باستخدام الجداول والرسوم والخرائط المناسبة مع توضيح الوحدات."},{"type":"text","text":"تقارن النتائج بمرجع مستقل أو قياس آخر لتقدير الفروق والتحقق من صلاحية الإجراء."},{"type":"text","text":"تكتب مناقشة علمية تفسر مصادر الخطأ وعدم اليقين وحدود التعميم."},{"type":"text","text":"يحفظ الناتج مع البيانات الخام وخطوات المعالجة والملفات الوصفية لسهولة إعادة التجربة."},{"type":"text","text":"مخرج النشاط: تقرير عملي يتضمن الهدف والمنهج والبيانات والنتائج والمناقشة والاستنتاجات."},{"type":"callout","text":"الخلاصة: المهارة العملية تكتمل عندما تكون القياسات موثقة والنتائج قابلة للتحقق وإعادة الإنتاج."}]}',5150,75,'["تنفيذ النشاط العملي وفق خطوات موثقة","فحص جودة القياسات والبيانات","إعداد تقرير وتحليل قابل لإعادة الإنتاج"]','تحليل الحالات والمشاريع التطبيقية'))
insert into public.academy_lessons(course_id,chapter_id,unit_id,slug,title,summary,content,published,sort_order,level,estimated_minutes,learning_objectives,chapter_title,unit_title)
select c.id,ch.id,case d.unit when 'التجارب والأجهزة والقياسات الميدانية' then u1.id else u2.id end,d.slug,d.title,d.summary,d.content::jsonb,false,d.ord,'advanced',d.mins,d.objectives::jsonb,'التطبيقات الميدانية والمختبرات العملية للأرصاد',d.unit from d cross join c cross join ch cross join u1 cross join u2
on conflict(course_id,slug) do update set chapter_id=excluded.chapter_id,unit_id=excluded.unit_id,title=excluded.title,summary=excluded.summary,content=excluded.content,published=false,sort_order=excluded.sort_order,level=excluded.level,estimated_minutes=excluded.estimated_minutes,learning_objectives=excluded.learning_objectives,chapter_title=excluded.chapter_title,unit_title=excluded.unit_title;